Use a set to track complements in O(n) time.

def two_sum_pairs(arr, k):
    seen = set()
    pairs = []
    for x in arr:
        if k - x in seen:
            pairs.append((k - x, x))
        seen.add(x)
    return pairs

Alternative: sort + two-pointer approach runs O(n log n) but uses O(1) extra space. The hash-set approach is preferred for interviews unless space is constrained.

Use collections.Counter to count frequencies, then iterate to find the first with count 1.

from collections import Counter
def first_unique(s):
    counts = Counter(s)
    for ch in s:
        if counts[ch] == 1:
            return ch
    return None

Time: O(n), Space: O(k) where k is alphabet size. Two-pass approach — first pass counts, second finds.

Floyd's cycle detection: use slow (1 step) and fast (2 step) pointers.

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

To find the cycle start: when slow == fast, reset one pointer to head and advance both by 1 — they meet at the cycle entry. O(n) time, O(1) space.

DFS uses a stack (or recursion), BFS uses a queue.

from collections import deque

def bfs(graph, start):
    visited, queue = set(), deque([start])
    visited.add(start)
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

def dfs(graph, start, visited=None):
    if visited is None: visited = set()
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited)
    return visited

BFS finds shortest path in unweighted graphs. DFS is better for detecting cycles and topological sorting.

Divide-and-conquer: pick a pivot, partition, recurse.

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    mid = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + mid + quicksort(right)

Average O(n log n), worst O(n^2) with bad pivot choice. In-place variant uses Lomuto or Hoare partitioning. Python's built-in sorted() uses Timsort (O(n log n) guaranteed).

A tree where each node represents a character prefix.

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word):
        node = self._find(word)
        return node is not None and node.is_end

    def starts_with(self, prefix):
        return self._find(prefix) is not None

Used for autocomplete, spell-check, IP routing. O(m) per operation where m is word length.

Count character frequencies and sum absolute differences.

from collections import Counter
def anagram_removals(s1, s2):
    c1, c2 = Counter(s1), Counter(s2)
    return sum((c1 - c2).values()) + sum((c2 - c1).values())

This gives the total characters to remove from both strings to make them anagrams. Counter subtraction only keeps positive counts, so we sum both directions. O(n + m) time.

class Node:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, val):
        self.head = Node(val, self.head)

    def find(self, val):
        curr = self.head
        while curr:
            if curr.val == val: return curr
            curr = curr.next
        return None

    def delete(self, val):
        if not self.head: return
        if self.head.val == val:
            self.head = self.head.next; return
        curr = self.head
        while curr.next:
            if curr.next.val == val:
                curr.next = curr.next.next; return
            curr = curr.next

Insert: O(1) at head. Find/Delete: O(n). Use a sentinel/dummy head node to simplify edge cases.

Split, reverse, rejoin.

def reverse_words(s):
    return ' '.join(s.split()[::-1])

split() without args handles multiple spaces. For in-place reversal (interview follow-up): reverse entire string, then reverse each word. Python strings are immutable, so true in-place requires a list of chars.

Use backtracking or itertools.permutations.

def permutations(s):
    if len(s) <= 1:
        return [s]
    result = []
    for i, ch in enumerate(s):
        rest = s[:i] + s[i+1:]
        for perm in permutations(rest):
            result.append(ch + perm)
    return result

Or simply: from itertools import permutations as p; list(p('abc'))

Time: O(n! * n). For deduplication with repeated chars, use a set or sort + skip approach.

Two pointers converging from both ends of a sorted array.

def two_sum_sorted(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        s = arr[left] + arr[right]
        if s == target:
            return (left, right)
        elif s < target:
            left += 1
        else:
            right -= 1
    return None

O(n) time, O(1) space. Works because the array is sorted. Also used for: container with most water, remove duplicates, three-sum (fix one + two-pointer on rest).

Halve the search space each iteration.

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

O(log n) time, O(1) space. Use bisect module in production: bisect.bisect_left(arr, target).

Two-pointer merge in O(n + m) time.

def merge_sorted(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

This is the merge step of merge sort. O(n + m) time and space. In Python, heapq.merge(a, b) does this lazily.

Compare string to its reverse, or use two pointers.

def is_palindrome(s):
    return s == s[::-1]

# Two-pointer (better for follow-ups):
def is_palindrome_tp(s):
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1; right -= 1
    return True

For alphanumeric-only: filter with isalnum() and lower() first. Extends to 'valid palindrome II' (remove at most one char).

Use a monotonic deque to track max in O(n).

from collections import deque
def max_sliding_window(nums, k):
    dq = deque()  # indices of useful elements
    result = []
    for i, num in enumerate(nums):
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        while dq and nums[dq[-1]] <= num:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

The deque stores indices in decreasing order of values. Front is always the max for the current window. O(n) total.
